import { PanelLeftClose,PanelLeftOpen,Mail, PackageOpen, Pill, Film, FilePenLine, BookOpen, CalendarDays, MessageCircle, LayoutDashboard, Library, ClipboardList, NotebookPen, Settings, ArrowUpRight, ArrowRight, Plus, ChevronLeft, ChevronRight, Check, X, Send, Square, Search, FolderPlus, Clock3, Sparkles, Sun, Moon, Globe2, ShieldCheck, Undo2, Trash2, Pencil, Download, GraduationCap, CircleHelp, Leaf } from 'lucide-react';
