type Page = 'home'|'assistant'|'calendar'|'library'|'exams'|'mistakes'|'settings'|'notes'|'videos'|'capsules'|'toolbox'|'email'|'browser';
interface DocumentRecord { id:string; name:string; source:string; status:string; size:number; error?:string; pages?:number;folderId?:string;relativePath?:string }
interface State { videos:TeachingVideo[]; folders:Array<{id:string;name:string;path:string;enabled:boolean;lastScan?:string;error?:string}>; events:StudyEvent[]; mistakes:Mistake[]; exams:PracticeTest[]; documents:DocumentRecord[]; preferences:StudentPreferences; activity:Array<{id:number; at:string; action:string; entity:string; undone:number}> }
const empty:State = {videos:[],folders:[],events:[],mistakes:[],exams:[],documents:[],preferences:{responseLanguage:'auto',reminders:true},activity:[]};
const math = createMathPlugin({ singleDollarTextMath:true });
const markdownComponents = { table: ({children}:{children?:ReactNode}) => <div className="markdown-table-scroll" tabIndex={0}><table>{children}</table></div> };
function Markdown({children}:{children:string}) { return <div className="markdown"><Streamdown components={markdownComponents} plugins={{math,cjk}} controls={false}>{mathMarkdown(children)}</Streamdown></div>; }
function dayKey(d:Date) { return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`; }
function localInput(value:string) { const d=new Date(value); return `${dayKey(d)}T${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`; }
function IconButton({label,onClick,children}:{label:string;onClick:()=>void;children:ReactNode}) { return <button className="icon-button" type="button" aria-label={label} title={label} onClick={onClick}>{children}</button>; }
function Empty({icon,title,description,action}:{icon:ReactNode;title:string;description?:string;action?:ReactNode}) { return <div className="empty"><span className="empty-icon">{icon}</span><h3>{title}</h3>{description&&<p>{description}</p>}{action}</div>; }
function Modal({title,close,children}:{title:string;close:()=>void;children:ReactNode}) { const ref=useRef<HTMLDialogElement>(null); useEffect(()=>{ref.current?.showModal(); return()=>ref.current?.close();},[]); return <dialog ref={ref} className="modal" onCancel={close} onClick={e=>{if(e.target===e.currentTarget)close();}}><header><h2>{title}</h2><IconButton label="Close / 关闭" onClick={close}><X size={19}/></IconButton></header>{children}</dialog>; }

export function Scoreler() {
  const [locale,setLocale]=useState<Locale>(()=>localStorage.getItem('scoreler.locale') as Locale || (navigator.language.startsWith('zh')?'zh-CN':'en'));
  const palette=usePalette();
  const customAppearance=useCustomThemes();
  const selectedTheme=customAppearance.value.themes.find(t=>t.id===customAppearance.value.selected);
  const [dark,setDark]=useState(()=>localStorage.getItem('scoreler.theme')==='dark');
  const [page,setPage]=useState<Page>('home');
  const [browserEnabled,setBrowserEnabled]=useState(false);
  useEffect(()=>{let active=true;const receive=(value:{enabled?:boolean})=>{if(!active)return;const enabled=value.enabled===true;setBrowserEnabled(enabled);if(!enabled)setPage(current=>current==='browser'?'settings':current);};void window.scorelerDesktop?.browser?.('state').then(receive).catch(()=>{});const off=window.scorelerDesktop?.onBrowserState?.(receive);return()=>{active=false;off?.();};},[]);
  const [sidebarHidden,setSidebarHidden]=useState(()=>localStorage.getItem('scoreler.sidebar-hidden')==='true');
  useEffect(()=>{localStorage.setItem('scoreler.sidebar-hidden',String(sidebarHidden));},[sidebarHidden]);
  const [setupTopic,setSetupTopic]=useState<SetupTopic|null>(null),[startupRequest,setStartupRequest]=useState(0);
  const openSetup=useCallback((topic:SetupTopic)=>{setSetupTopic(topic);setPage(['models','web-search'].includes(topic)?'settings':topic==='email'?'email':topic==='browser'?'browser':topic==='agent'?'assistant':'toolbox');if(topic==='quickstart'){setStartupRequest(n=>n+1);setToolRequest(previous=>({id:'startup',key:previous.key+1}));}},[]);
  useEffect(()=>window.scorelerDesktop?.onSetupOpen?.(topic=>{if(setupTopics.includes(topic as SetupTopic))openSetup(topic as SetupTopic);}),[openSetup]);
  const [browserTarget,setBrowserTarget]=useState<{id:number;url:string}|null>(null);
  const openEmailLink=useCallback((value:string)=>{void (async()=>{try{const url=new URL(value);if(url.protocol==='https:'&&(await window.scorelerDesktop?.browser?.('state'))?.enabled===true){setBrowserTarget(previous=>({id:(previous?.id??0)+1,url:url.href}));setPage('browser');}else if(['https:','http:','mailto:'].includes(url.protocol)){void window.scorelerDesktop?.browser?.('open-link',url.href).catch(e=>setNotice(String(e)));}else throw Error('Unsupported email link');}catch(error){setNotice(String(error));}})();},[]);
  const [focusDate,setFocusDate]=useState(new Date());
  const reducedMotion=useReducedMotion();
  const [state,setState]=useState<State>(empty),[loading,setLoading]=useState(true),[error,setError]=useState(''),[notice,setNotice]=useState('');
  const navigation=useFeatureLayout(setNotice);
  const [dragging,setDragging]=useState(false),[activeTool,setActiveTool]=useState<ToolFeature|null>(null),[toolRequest,setToolRequest]=useState<{id:ToolFeature|null;key:number}>({id:null,key:0}),[dictationId,setDictationId]=useState<string>();
  const openFeature=(id:FeatureId)=>{if(toolFeatures.includes(id as ToolFeature)){setToolRequest(previous=>({id:id as ToolFeature,key:previous.key+1}));setPage('toolbox');}else setPage(id as Page);};
  const openDictation=(id:string)=>{setDictationId(id);openFeature('dictation');};
  const [event,setEvent]=useState<Partial<StudyEvent>|null>(null),[mistake,setMistake]=useState<Partial<Mistake>|null>(null);
  const [initialPrompt,setInitialPrompt]=useState('');
  const [autoSend,setAutoSend]=useState<{id:string;text:string;images?:InlineImage[]}|null>(null);
  useEffect(()=>window.scorelerDesktop?.onCompanionPrompt?.(message=>{setAutoSend({id:crypto.randomUUID(),...(typeof message==='string'?{text:message}:message)});setPage('assistant');}),[]);
  useEffect(()=>{void window.scorelerDesktop?.setCompanion?.({locale,theme:dark?'dark':'light',palette}).catch(()=>{});},[locale,dark,palette]);
  useEffect(()=>window.scorelerDesktop?.onMailArrived?.(value=>setNotice(value.title+' · '+value.body)),[]);
  useEffect(()=>window.scorelerDesktop?.onMailOpen?.(()=>setPage('email')),[]);
  const t:Copy=copy[locale] ?? copy.en;
  const refresh=useCallback(async()=>{try{setState({...empty,...await apiFetch<State>('/api/student/state')}); setError('');}catch(e){setError(e instanceof Error?e.message:String(e));}finally{setLoading(false);}},[]);
  useEffect(()=>{if(!setupTopic)return;const timer=setTimeout(()=>{if(page==='toolbox'&&setupTopic==='quickstart')window.scrollTo({top:0});else if(page==='settings'||page==='toolbox')document.getElementById('setup-'+setupTopic)?.scrollIntoView({block:'start',behavior:'instant'});},150);return()=>clearTimeout(timer);},[page,setupTopic]);
  useEffect(()=>{void refresh(); const id=setInterval(()=>void refresh(),5000);return()=>clearInterval(id);},[refresh]);
  useEffect(()=>{localStorage.setItem('scoreler.locale',locale);document.documentElement.lang=locale;},[locale]);
  useEffect(()=>{document.documentElement.dataset.palette=palette;},[palette]);
  useEffect(()=>{const root=document.documentElement,variables:Record<string,string>=selectedTheme?themeVariables(selectedTheme):{'--on-accent':dark?'#101010':'#ffffff'};for(const [key,value] of Object.entries(variables))root.style.setProperty(key,value);if(selectedTheme?.image)root.style.setProperty('--custom-background','url("'+selectedTheme.image+'")');
   let cancelled=false;const timer=setTimeout(()=>{if(!cancelled&&customAppearance.loaded)void syncDesktopAppearance({palette,theme:dark?'dark':'light',locale,variables,...(selectedTheme?.image?{image:selectedTheme.image}:{})}).catch(()=>{});},100);
   return()=>{cancelled=true;clearTimeout(timer);for(const key of Object.keys(variables))root.style.removeProperty(key);root.style.removeProperty('--custom-background');};
  },[selectedTheme,palette,dark,locale,customAppearance.loaded]);
  useEffect(()=>{localStorage.setItem('scoreler.theme',dark?'dark':'light');document.documentElement.dataset.theme=dark?'dark':'light';},[dark]);
  useEffect(()=>{if(notice){const id=setTimeout(()=>setNotice(''),5000);return()=>clearTimeout(id);}},[notice]);
  const reminded=useRef(new Set<string>());
  useEffect(()=>{if(!state.preferences.reminders)return; const check=()=>{for(const e of state.events){const gap=Date.parse(e.start)-Date.now();if(!e.completed&&gap>=0&&gap<5*60000&&!reminded.current.has(e.id)){reminded.current.add(e.id);setNotice(`${t.upcomingReminder}: ${e.title}`);}}};check();const id=setInterval(check,30000);return()=>clearInterval(id);},[state.events,state.preferences.reminders,t.upcomingReminder]);
  const perform=async(path:string,method='POST',body?:unknown)=>{const result=await apiFetch(path,{method,...(body!==undefined?{body:JSON.stringify(body)}:{})});await refresh();return result;};
  const safe=async(work:()=>Promise<unknown>)=>{try{await work();}catch(e){setNotice(e instanceof Error?e.message:String(e));}};
  const sendToAI=(text:string)=>{setAutoSend(null);setInitialPrompt(text);setPage('assistant');};
  const ask=(prompt:string)=>{setInitialPrompt(prompt);setPage('assistant');};
  const now=new Date(), today=dayKey(focusDate);
  const todayEvents=state.events.filter(e=>dayKey(new Date(e.start))===today&&(e.kind!=='lesson'||Date.parse(e.end)>now.getTime())).sort((a,b)=>a.start.localeCompare(b.start));
  const deadlines=state.events.filter(e=>!e.completed&&['assignment','exam'].includes(e.kind)).sort((a,b)=>Date.parse(a.start)-Date.parse(b.start));
  const date=(value:string,options:Intl.DateTimeFormatOptions={month:'short',day:'numeric'})=>new Date(value).toLocaleDateString(locale,options);
  const time=(value:string)=>new Date(value).toLocaleTimeString(locale,{hour:'2-digit',minute:'2-digit'});
  const subjectName=(name:string)=>name;
  const eventRow=(e:StudyEvent)=> <div className={`event-row ${e.completed?'is-completed':''}`} key={e.id}><button className={`completion ${e.completed?'checked':''}`} aria-label={`${t.complete}: ${e.title}`} onClick={()=>void safe(()=>perform('/api/student/events','PUT',{...e,completed:!e.completed}))}>{e.completed&&<Check size={13}/>}</button><button className="event-main" onClick={()=>setEvent(e)}><strong>{e.title}</strong><span>{subjectName(e.subject)||t[e.kind]} · {time(e.start)}–{time(e.end)}</span></button><span className={`kind ${e.kind}`}>{t[e.kind]}</span></div>;

  return <div className={`scoreler ${sidebarHidden?'sidebar-hidden':''}`}><aside className="sidebar"><a className="brand" href="#" aria-label="Scoreler" title="Scoreler" onClick={e=>{e.preventDefault();setPage('home');}}><span className="brand-mark"><Mascot/></span><span className="brand-name">Scoreler</span></a><button className="sidebar-toggle text-button" title={sidebarHidden?(locale==='en'?'Expand sidebar':'展开侧栏'):(locale==='en'?'Collapse sidebar':'收起侧栏')} aria-label={sidebarHidden?(locale==='en'?'Expand sidebar':'展开侧栏'):(locale==='en'?'Collapse sidebar':'收起侧栏')} aria-expanded={!sidebarHidden} onClick={()=>setSidebarHidden(value=>!value)}>{sidebarHidden?<PanelLeftOpen size={18}/>:<PanelLeftClose size={18}/>}<span>{locale==='en'?'Collapse sidebar':'收起侧栏'}</span></button><div className="space-label">{locale==='en'?'Workspace':'学习空间'}</div><nav aria-label={t.workspace} onDragOver={e=>{if(dragging)e.preventDefault();}} onDrop={e=>{const id=draggedFeature(e);if(id){e.preventDefault();navigation.move(id,'sidebar');setDragging(false);}}}>{navigation.layout.sidebar.filter(id=>id!=='browser'||browserEnabled).map(id=>{const item=featureCatalog[id],Icon=item.icon,label=locale==='en'?item.en:item.zh,selected=page===id||(page==='toolbox'&&activeTool===id);return <button key={id} draggable={navigation.ready} aria-label={label} title={label} className={selected?'active':''} onDragStart={e=>{e.dataTransfer.setData(featureDragType,id);e.dataTransfer.effectAllowed='move';setDragging(true);}} onDragEnd={()=>setDragging(false)} onDragOver={e=>{if(dragging)e.preventDefault();}} onDrop={e=>{const moved=draggedFeature(e);if(moved){e.preventDefault();e.stopPropagation();navigation.move(moved,'sidebar',id);setDragging(false);}}} onClick={()=>openFeature(id)}><Icon size={18} strokeWidth={1.7}/><span>{label}</span>{selected&&<motion.span className="nav-selection" layoutId="scoreler-navigation" transition={reducedMotion?{duration:0}:{type:'spring',bounce:0,duration:.25}}/>}</button>;})}<button className={page==='toolbox'&&!activeTool?'active':''} aria-label={locale==='en'?'Toolbox':'百宝箱'} title={dragging?(locale==='en'?'Drop here to move into Toolbox':'拖到这里移入百宝箱'):(locale==='en'?'Toolbox':'百宝箱')} onDragOver={e=>{if(dragging)e.preventDefault();}} onDrop={e=>{const id=draggedFeature(e);if(id){e.preventDefault();e.stopPropagation();navigation.move(id,'toolbox');setDragging(false);setToolRequest(previous=>({id:null,key:previous.key+1}));setPage('toolbox');}}} onClick={()=>{setToolRequest(previous=>({id:null,key:previous.key+1}));setPage('toolbox');}}><PackageOpen size={18}/><span>{locale==='en'?'Toolbox':'百宝箱'}{dragging?(locale==='en'?' · Drop here':' · 拖入'):''}</span></button></nav><div className="sidebar-bottom"><button aria-label={t.settings} title={t.settings} className={`settings-nav ${page==='settings'?'active':''}`} onClick={()=>setPage('settings')}><Settings size={18}/><span>{t.settings}</span></button><div className="sidebar-footer"><ShieldCheck size={13}/><span>{t.local}</span></div></div></aside>
    <div className="main-shell"><main className={`content page-${page}`}>
      {error&&<div role="alert" className="error-banner">{t.connectionError} {error}<button onClick={()=>void refresh()}>{t.retry}</button></div>}
      {loading?<div className="loading"><BookOpen/>{t.loading}</div>:<>
      {page==='home'&&<div className="today-view"><div className="today-heading"><div><span className="overline">{locale==='en'?'YOUR SCHEDULE':'我的日程'}</span><h1>{date(focusDate.toISOString(),{weekday:'long',month:'long',day:'numeric'})}</h1></div><div className="button-row"><button className="secondary theme-toggle" aria-pressed={dark} title={locale==='en'?(dark?'Switch to light mode':'Switch to dark mode'):(dark?'切换到浅色模式':'切换到深色模式')} onClick={()=>setDark(value=>!value)}>{dark?<Sun size={16}/>:<Moon size={16}/>}<span>{locale==='en'?(dark?'Light mode':'Dark mode'):(dark?'浅色模式':'深色模式')}</span></button><PetToggle en={locale==='en'} notice={setNotice}/><button className="primary" onClick={()=>setEvent({})}><Plus size={16}/>{t.addEvent}</button></div></div>
        <Encouragement en={locale==='en'}/><div className="today-columns"><div className="today-primary"><div className="week-strip" aria-label={locale==='en'?'Choose a day':'选择日期'}>{Array.from({length:7},(_,i)=>{const d=new Date(now);d.setDate(now.getDate()-((now.getDay()+6)%7)+i);return <button key={i} aria-pressed={dayKey(d)===today} className={dayKey(d)===today?'selected':''} onClick={()=>setFocusDate(d)}><span>{d.toLocaleDateString(locale,{weekday:'short'})}</span><strong>{d.getDate()}</strong><i className={state.events.some(e=>dayKey(new Date(e.start))===dayKey(d))?'has-events':''}/></button>;})}</div>
          <section className="agenda-section"><div className="section-heading"><h2>{dayKey(focusDate)===dayKey(now)?t.today:date(focusDate.toISOString(),{month:'short',day:'numeric'})}</h2><span className="agenda-count">{todayEvents.length} {locale==='en'?'events':'项日程'}</span></div>{todayEvents.length?todayEvents.map(eventRow):<div className="agenda-empty"><CalendarDays size={27} strokeWidth={1.25}/><h3>{locale==='en'?'No events scheduled':'暂无日程'}</h3><p>{locale==='en'?'Your lessons, deadlines and study sessions will appear here.':'课程、截止日期和学习安排会显示在这里。'}</p><button className="text-button" onClick={()=>setEvent({})}>{t.addEvent}</button></div>}</section>
          <section className="deadline-section"><div className="section-heading"><h2>{locale==='en'?'Tasks & deadlines':'待办与截止日期'}</h2><button className="text-button" onClick={()=>setPage('calendar')}>{locale==='en'?'Show all':'查看全部'}<ChevronRight size={13}/></button></div>{deadlines.length?deadlines.map(e=><button className={`deadline-row ${Date.parse(e.start)<Date.now()?'overdue':''}`} key={e.id} onClick={()=>setEvent(e)}><span className={`deadline-dot ${e.kind}`}/><div><strong>{e.title}</strong><span>{subjectName(e.subject)}</span></div><time>{date(e.start)}{Date.parse(e.start)<Date.now()&&<span className="deadline-overdue">{locale==='en'?'Overdue':'已逾期'}</span>}</time><ChevronRight size={13}/></button>):<p className="inline-empty">{locale==='en'?'No unfinished assignments or exams.':'暂无未完成的作业或考试。'}</p>}</section>
        </div><aside className="today-detail"><section className="study-tools"><h2>{locale==='en'?'Study':'学习'}</h2><button onClick={()=>ask(t.planPrompt)}><CalendarDays size={17}/><span>{t.planWeek}</span><ChevronRight size={13}/></button><button onClick={()=>ask(t.practicePrompt)}><ClipboardList size={17}/><span>{t.generate}</span><ChevronRight size={13}/></button><button onClick={()=>setPage('library')}><FolderPlus size={17}/><span>{t.importFiles}</span><ChevronRight size={13}/></button></section><HomeChatBox locale={locale} onSend={text=>{setInitialPrompt('');setAutoSend({id:crypto.randomUUID(),text});setPage('assistant');}}/></aside></div>
      </div>}
      {page==='assistant'&&<Assistant t={t} locale={locale} initialPrompt={initialPrompt} autoSend={autoSend} consumeAutoSend={()=>setAutoSend(null)} consume={()=>setInitialPrompt('')} responseLanguage={state.preferences.responseLanguage} changed={refresh} notice={setNotice} videos={state.videos} openDictation={openDictation}/>}
      {page==='calendar'&&<><Heading title={t.calendar} description={t.welcome} action={<><button className="secondary" onClick={()=>void safe(()=>perform('/api/student/undo'))}><Undo2 size={15}/>{t.undo}</button><button className="primary" onClick={()=>setEvent({})}><Plus size={16}/>{t.addEvent}</button></>}/><CalendarView t={t} locale={locale} anchor={focusDate} setAnchor={setFocusDate} events={state.events} onEdit={setEvent} onAdd={start=>setEvent({start})}/><div className="calendar-footer"><button className="text-button" onClick={()=>ask(t.planPrompt)}><Sparkles size={15}/>{t.planWeek}<ArrowRight size={15}/></button></div><section className="panel activity"><h2>{t.activity}</h2>{state.activity.length?state.activity.slice(0,8).map(a=><div key={a.id}><span>{a.undone?'↶':(a.action==='create'||a.action==='batch-create')?'+':a.action==='delete'?'−':'↗'} {t[(a.action==='create'||a.action==='batch-create')?'addEvent':a.action==='delete'?'delete':'edit']}</span><time>{new Date(a.at).toLocaleString(locale)}</time></div>):<p>{t.noActivity}</p>}</section></>}
      {page==='library'&&<WorkspaceLibrary t={t} locale={locale} ask={ask} folders={state.folders} documents={state.documents} refresh={refresh} notice={setNotice}/>}
      {page==='exams'&&<Exams t={t} locale={locale} exams={state.exams} changed={refresh} sendToAI={sendToAI} ask={ask} notice={setNotice}/>}
      {page==='mistakes'&&<><Heading title={t.mistakesTitle} description={t.mistakesDescription} action={<button className="primary" onClick={()=>setMistake({subject:''})}><Plus size={16}/>{t.addMistake}</button>}/>{<SubjectFolders items={state.mistakes} en={locale==='en'} kind="mistakes">{items=><MistakeSelection items={items} locale={locale} ask={sendToAI} notice={setNotice}>{selection=><div className="mistakes-grid">{items.map(m=><section className={`panel mistake-card ${selection.active&&selection.has(m.id)?'is-picked':''}`} key={m.id}>{selection.active&&<label className="mistake-pick"><input type="checkbox" checked={selection.has(m.id)} onChange={()=>selection.toggle(m.id)} aria-label={`${locale==='en'?'Select':'选择'} ${m.topic}`}/>{locale==='en'?'Select mistake':'选择错题'}</label>}<div className="section-heading"><span className="kind">{subjectName(m.subject)}</span><button className={`text-button ${m.resolved?'resolved':''}`} onClick={()=>void safe(()=>perform('/api/student/mistakes','PUT',{...m,resolved:!m.resolved}))}>{m.resolved?<Check size={14}/>:<Clock3 size={14}/>} {m.resolved?t.resolved:t.revisit}</button></div><h2>{m.topic}</h2><Markdown>{m.question==='[Screenshot question]'?(locale==='en'?'Question screenshot':'题目截图'):m.question}</Markdown><MistakeScreenshots images={m.images} field="question"/>{(m.answer||m.images?.some(i=>i.field==='answer'))&&<><h4>{t.attempted}</h4><p>{m.answer}</p><MistakeScreenshots images={m.images} field="answer"/></>}{(m.correction||m.images?.some(i=>i.field==='correction'))&&<div className="correction"><h4>{t.correction}</h4><Markdown>{m.correction}</Markdown><MistakeScreenshots images={m.images} field="correction"/></div>}<div className="button-row"><ExportMenu en={locale==='en'} notice={setNotice} run={format=>exportMistake(m,locale,format)}/><button className="text-button" onClick={()=>setMistake(m)}><Pencil size={14}/>{t.edit}</button><button className="text-button" onClick={()=>ask(`${t.similar}: ${m.topic}. ${m.question}\nPlease include the screenshots saved with this mistake.\nMy earlier mistake: ${m.answer}\nCorrection: ${m.correction}\nUse a new original question and hints first.`)}>{t.similar}<ArrowRight size={14}/></button></div></section>)}</div>}</MistakeSelection>}</SubjectFolders>}</>}
      {page==='email'&&<EmailPage en={locale==='en'} notice={setNotice} sendToAI={sendToAI} openLink={openEmailLink}/>}
      {page==='browser'&&<StudyBrowser en={locale==='en'} notice={setNotice} target={browserTarget} targetOpened={()=>setBrowserTarget(null)}/>}
      {page==='toolbox'&&<Toolbox locale={locale} notice={setNotice} openSetup={openSetup} ask={sendToAI} startupRequest={startupRequest} toolRequest={toolRequest} onToolChange={setActiveTool} dictationId={dictationId} layout={navigation.layout} move={navigation.move} resetLayout={navigation.reset} openFeature={openFeature} browserEnabled={browserEnabled} onDragChange={setDragging}/>}
      {page==='capsules'&&<MemoryCapsules locale={locale} notice={setNotice}/>}
      {page==='notes'&&<NoteLibrary locale={locale} ask={sendToAI} notice={setNotice}/>}
      {page==='videos'&&<VideoLibrary videos={state.videos} locale={locale} ask={sendToAI} notice={setNotice} refresh={refresh}/>}
      {page==='settings'&&<SettingsPage t={t} locale={locale} setLocale={setLocale} dark={dark} setDark={setDark} preferences={state.preferences} savePreferences={p=>safe(()=>perform('/api/student/preferences','PUT',p))} notice={setNotice}/>}
      </>}
      </main>
    </div>
    {notice&&<div className="toast" role="status">{notice}<IconButton label={t.close} onClick={()=>setNotice('')}><X size={14}/></IconButton></div>}
    {event&&<EventEditor t={t} event={event} close={()=>setEvent(null)} save={e=>safe(async()=>{await perform('/api/student/events',event.id?'PUT':'POST',e);setEvent(null);})} remove={event.id?()=>{if(window.confirm(t.confirmDelete))void safe(async()=>{await perform(`/api/student/events/${event.id}`,'DELETE');setEvent(null);});}:undefined}/>}
    {mistake&&<MistakeEditor t={t} mistake={mistake} close={()=>setMistake(null)} save={m=>safe(async()=>{await perform('/api/student/mistakes',mistake.id?'PUT':'POST',m);setMistake(null);})}/>}
  </div>;
}

function Heading({title,description,action}:{title:string;description:string;action?:ReactNode}) { return <div className="page-heading"><div><h1>{title}</h1><p>{description}</p></div>{action&&<div className="button-row">{action}</div>}</div>; }
export function EventEditor({t,event,close,save,remove}:{t:Copy;event:Partial<StudyEvent>;close:()=>void;save:(e:unknown)=>Promise<unknown>;remove?:()=>void}) {
  const start=event.start??new Date(Date.now()+3600000).toISOString();
  const submit=(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();const f=new FormData(e.currentTarget);void save({...event,title:f.get('title'),subject:event.subject??'',kind:f.get('kind'),start:new Date(String(f.get('start'))).toISOString(),end:new Date(String(f.get('end'))).toISOString(),completed:(e.nativeEvent as SubmitEvent).submitter?.getAttribute('name')==='toggle-completed'?!event.completed:event.completed??false});};
  return <Modal title={event.id?t.edit:t.addEvent} close={close}><form onSubmit={submit}><label>{t.title}<input autoFocus required name="title" maxLength={200} defaultValue={event.title}/></label><div className="form-grid"><label>{t.kind}<select name="kind" defaultValue={event.kind??'study'}>{(['study','lesson','assignment','exam'] as const).map(k=><option key={k} value={k}>{t[k]}</option>)}</select></label><label>{t.start}<input required name="start" type="datetime-local" defaultValue={localInput(start)}/></label><label>{t.end}<input required name="end" type="datetime-local" defaultValue={localInput(event.end??new Date(Date.parse(start)+45*60000).toISOString())}/></label></div><div className="modal-actions">{remove&&<button className="danger text-button" type="button" onClick={remove}><Trash2 size={15}/>{t.delete}</button>}<button type="button" className="secondary" onClick={close}>{t.cancel}</button>{event.id&&<button type="submit" name="toggle-completed" className="secondary"><Check size={15}/>{event.completed?(t.cancel==='Cancel'?'Mark unfinished':'标记未完成'):(t.cancel==='Cancel'?'Mark finished':'标记完成')}</button>}<button className="primary" type="submit">{t.save}</button></div></form></Modal>;
}
function MistakeEditor({t,mistake,close,save}:{t:Copy;mistake:Partial<Mistake>;close:()=>void;save:(m:unknown)=>Promise<unknown>}) {
 const [images,setImages]=useState<MistakeImage[]>(mistake.images??[]);const en=t.cancel==='Cancel';
 return <Modal title={t.addMistake} close={close}><form onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);void save({...mistake,...Object.fromEntries(f.entries()),images});}}><label>{t.subject}<input name="subject" required defaultValue={mistake.subject} placeholder={en?"e.g. Chemistry":"例如：化学"}/></label><label>{t.topic}<input name="topic" required defaultValue={mistake.topic}/></label>{(['question','answer','correction'] as const).map(field=><ScreenshotField key={field} field={field} label={t[field==='answer'?'attempted':field]} defaultValue={mistake[field]} images={images} change={setImages} en={en}/>)}<div className="modal-actions"><button type="button" className="secondary" onClick={close}>{t.cancel}</button><button type="submit" className="primary">{t.save}</button></div></form></Modal>;
}

function CalendarView({t,locale,anchor,setAnchor,events,onEdit,onAdd}:{t:Copy;locale:Locale;anchor:Date;setAnchor:(d:Date)=>void;events:StudyEvent[];onEdit:(e:StudyEvent)=>void;onAdd:(start:string)=>void}) {
  const [view,setView]=useState<CalendarViewMode>(()=>{const saved=localStorage.getItem('scoreler.calendarView');return saved==='week'||saved==='day'?saved:'month';});
  const changeView=(value:CalendarViewMode)=>{setView(value);localStorage.setItem('scoreler.calendarView',value);};
  const shown=calendarDays(anchor,view),selected=dayKey(anchor);
  const dateLabel=(d:Date)=>d.toLocaleDateString(locale,{year:'numeric',month:'short',day:'numeric'});
  const rangeLabel=view==='month'?anchor.toLocaleDateString(locale,{month:'long',year:'numeric'}):view==='week'?`${dateLabel(shown[0])} – ${dateLabel(shown[6])}`:anchor.toLocaleDateString(locale,{year:'numeric',month:'long',day:'numeric',weekday:'long'});
  const rangeEvents=events.filter(e=>shown.some(d=>eventsOnDate([e],d).length));
  const nextEvent=[...events].sort((a,b)=>Date.parse(a.start)-Date.parse(b.start)).find(e=>Date.parse(e.start)>=shown[shown.length-1].getTime()+86400000);
  return <section className="panel calendar"><div className="calendar-toolbar"><div><h2 aria-live="polite">{rangeLabel}</h2><div className="button-row"><IconButton label={`${t.previous} ${t[view]}`} onClick={()=>setAnchor(shiftCalendar(anchor,view,-1))}><ChevronLeft size={17}/></IconButton><button className="secondary small" onClick={()=>setAnchor(new Date())}>{t.today}</button><IconButton label={`${t.next} ${t[view]}`} onClick={()=>setAnchor(shiftCalendar(anchor,view,1))}><ChevronRight size={17}/></IconButton></div></div><div className="calendar-controls"><input type="date" aria-label={locale==='en'?'Calendar date':'日历日期'} value={selected} onChange={e=>{if(e.target.value){const [y,m,d]=e.target.value.split('-').map(Number);setAnchor(new Date(y,m-1,d));}}}/><div className="segmented">{(['month','week','day'] as const).map(v=><button aria-pressed={view===v} className={view===v?'selected':''} key={v} onClick={()=>changeView(v)}>{t[v]}</button>)}</div></div></div>
    {view==='month'&&<div className="weekdays">{shown.slice(0,7).map(d=><span key={dayKey(d)}>{d.toLocaleDateString(locale,{weekday:'short'})}</span>)}</div>}
    {view!=='month'&&!rangeEvents.length&&<div className="calendar-empty-range"><span>{locale==='en'?'No events in this date range.':'这个日期范围内暂无日程。'}</span>{nextEvent&&<button className="text-button" onClick={()=>setAnchor(new Date(nextEvent.start))}>{locale==='en'?'Go to next scheduled event':'查看下一项日程'} · {dateLabel(new Date(nextEvent.start))}<ArrowRight size={14}/></button>}</div>}
    {view==='day'?<DayTimeline day={anchor} events={events} locale={locale} t={t} onEdit={onEdit} onAdd={onAdd}/>:<div className={`calendar-grid ${view}`}>{shown.map(d=>{const key=dayKey(d),items=eventsOnDate(events,d);return <div data-date={key} key={key} className={`calendar-cell ${view==='month'&&d.getMonth()!==anchor.getMonth()?'muted':''} ${key===dayKey(new Date())?'is-today':''} ${key===selected?'is-selected':''}`}><div className="cell-heading"><button className="calendar-date" aria-label={`${locale==='en'?'View day':'查看日期'}: ${dateLabel(d)}`} aria-pressed={key===selected} onClick={()=>{setAnchor(d);changeView('day');}}>{view!=='month'&&d.toLocaleDateString(locale,{weekday:'short'})} <b>{d.getDate()}</b></button><IconButton label={`${t.addEvent}: ${key}`} onClick={()=>{setAnchor(d);const a=new Date(d);a.setHours(16,0,0,0);onAdd(a.toISOString());}}><Plus size={12}/></IconButton></div>{items.map(e=><button key={e.id} className={`calendar-event ${e.kind} ${e.completed?'is-completed':''}`} onClick={()=>{setAnchor(d);onEdit(e);}}><span>{new Date(e.start).toLocaleTimeString(locale,{hour:'2-digit',minute:'2-digit'})}{view!=='month'&&`–${new Date(e.end).toLocaleTimeString(locale,{hour:'2-digit',minute:'2-digit'})}`}</span><strong>{e.title}</strong>{e.completed&&<Check size={11}/>}</button>)}{view!=='month'&&!items.length&&<p className="calendar-day-empty">{locale==='en'?'No events':'暂无日程'}</p>}</div>;})}</div>}</section>;
}


function Assistant({t,locale,initialPrompt,autoSend,consumeAutoSend,consume,changed,notice,videos,openDictation}:{t:Copy;locale:Locale;initialPrompt:string;autoSend:{id:string;text:string;images?:InlineImage[]}|null;consumeAutoSend:()=>void;consume:()=>void;responseLanguage:StudentPreferences['responseLanguage'];changed:()=>Promise<void>;notice:(s:string)=>void;videos:TeachingVideo[];openDictation:(id:string)=>void;}) {
  const [sessions,setSessions]=useState<SessionMeta[]>([]),[sessionId,setSessionId]=useState<string|null>(()=>autoSend?null:localStorage.getItem('scoreler.session'));
  const [messages,setMessages]=useState<ChatMessage[]>([]),[prompt,setPrompt]=useState(initialPrompt),[busy,setBusy]=useState(false),[status,setStatus]=useState('');
  const [openNote,setOpenNote]=useState<NoteLink|null>(null);
  const [thinking,setThinking]=useState(false);
  const [images,setImages]=useState<Array<InlineImage & {id:string;name:string}>>([]),[readingImages,setReadingImages]=useState(false);
  const imageInput=useRef<HTMLInputElement>(null);
  const [documents,setDocuments]=useState<Array<{id:string;name:string}>>([]);
  const addImages=async(files:File[])=>{if(busy||readingImages)return;setReadingImages(true);try{const added:Array<InlineImage & {id:string;name:string}>=[];for(const file of files){if(!['image/png','image/jpeg','image/webp','image/gif'].includes(file.type))throw new Error(locale==='en'?'Choose PNG, JPEG, WebP or GIF images.':'请选择 PNG、JPEG、WebP 或 GIF 图片。');if(file.size>5*1024*1024)throw new Error(locale==='en'?'Each image must be under 5 MB.':'每张图片不能超过 5 MB。');const data=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(new Error('Unable to read image'));reader.readAsDataURL(file);});added.push({id:crypto.randomUUID(),name:file.name||'Screenshot',mimeType:file.type,data});}setImages(current=>[...current,...added].slice(0,4));if(images.length+added.length>4)notice(locale==='en'?'Up to 4 images per message.':'每条消息最多 4 张图片。');}catch(e){notice(e instanceof Error?e.message:String(e));}finally{setReadingImages(false);if(imageInput.current)imageInput.current.value='';}};
  const addAttachments=async(files:File[])=>{if(busy||readingImages)return;const pictures=files.filter(file=>file.type.startsWith('image/')),docs=files.filter(file=>!file.type.startsWith('image/'));if(pictures.length)await addImages(pictures);if(!docs.length)return;setReadingImages(true);try{for(const file of docs.slice(0,8-documents.length)){if(!/\.(pdf|docx|xlsx|pptx|md|txt|csv|json)$/i.test(file.name))throw Error(locale==='en'?'Choose PDF, DOCX, XLSX, PPTX, Markdown or text files.':'请选择 PDF、DOCX、XLSX、PPTX、Markdown 或文本文件。');if(file.size>20*1024*1024)throw Error(locale==='en'?'Each file must be under 20 MB.':'单个文件不能超过 20 MB。');const data=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});const doc=await apiFetch<{id:string;name:string}>('/api/student/chat-attachment',{method:'POST',body:JSON.stringify({name:file.name,data})});setDocuments(old=>[...old,doc]);}if(docs.length+documents.length>8)notice(locale==='en'?'Up to 8 files per message.':'每条消息最多 8 个文件。');await changed();}catch(error){notice(String(error));}finally{setReadingImages(false);if(imageInput.current)imageInput.current.value='';}};
  const abortRef=useRef<AbortController|null>(null),turnRef=useRef(''),bottom=useRef<HTMLDivElement>(null);
  const refreshHistory=()=>listSessions().then(setSessions).catch(e=>notice(String(e)));
  useEffect(()=>{void refreshHistory();if(sessionId)void getSession(sessionId).then(s=>setMessages(s.messages)).catch(()=>{setSessionId(null);localStorage.removeItem('scoreler.session');});return()=>{abortRef.current?.abort();};},[]);
  useEffect(()=>{if(initialPrompt){setPrompt(initialPrompt);consume();}},[initialPrompt]);
  useEffect(()=>{bottom.current?.scrollIntoView({behavior:'smooth',block:'end'});},[messages,status]);
  const open=async(id:string)=>{if(busy)return;try{const s=await getSession(id);setSessionId(id);localStorage.setItem('scoreler.session',id);setMessages(s.messages);}catch(e){notice(String(e));}};
  const stop=()=>{abortRef.current?.abort();if(sessionId&&turnRef.current)void abortChat(sessionId,turnRef.current).catch(e=>notice(String(e)));};
  const sendMessage=async(message?:string,fresh=false,requestId:string=crypto.randomUUID(),attachments?:InlineImage[])=>{
    if((!(message??prompt).trim()&&!(attachments??images).length&&!documents.length)||busy||readingImages)return;
    const sentImages=(attachments??images).map(image=>({...image,id:'id'in image?String(image.id):crypto.randomUUID(),name:'name'in image?String(image.name):'Screenshot'}));const sentDocuments=fresh?[]:documents;const plainPrompt=(message??prompt).trim()||(locale==='en'?'Help me with the attached study material.':'请使用附加的学习资料帮助我。');const userPrompt=plainPrompt+sentDocuments.map(doc=>'\n\n['+doc.name.replace(/[\[\]\n\r]/g,'_')+'](scoreler-document:'+doc.id+')').join('');setPrompt('');setImages([]);setDocuments([]);setBusy(true);setThinking(true);setStatus(t.thinking);
    const controller=new AbortController();abortRef.current=controller;
    try {
      const id=(fresh?null:sessionId)??(await createSession()).id;setSessionId(id);localStorage.setItem('scoreler.session',id);
      setMessages(m=>[...(fresh?[]:m),{role:'user',content:userPrompt,timestamp:Date.now(),images:sentImages.map(image=>({previewUrl:`data:${image.mimeType};base64,${image.data}`,mimeType:image.mimeType}))},{role:'assistant',content:'',timestamp:Date.now()}]);
      for await(const envelope of streamChat(userPrompt,id,requestId,controller.signal,sentImages.map(({data,mimeType})=>({data,mimeType})))){
        turnRef.current=envelope.turnId;const ev=envelope.event;
        if(ev.type==='text_delta'){setStatus('');setMessages(m=>m.map((v,i)=>i===m.length-1?{...v,content:v.content+ev.delta}:v));}
        if(ev.type==='thinking_start'){setThinking(true);setMessages(m=>m.map((v,i)=>i===m.length-1?{...v,traceEvents:[...(v.traceEvents??[]),{event:{type:'thinking_start'}}]}:v));}
        if(ev.type==='thinking_end'||ev.type==='text_delta'||ev.type==='tool_start')setThinking(false);
        if(ev.type==='tool_start')setMessages(m=>m.map((v,i)=>i===m.length-1?{...v,tools:[...(v.tools??[]),{toolCallId:ev.toolCallId,toolName:ev.toolName,args:ev.args}]}:v));
        if(ev.type==='tool_end')setMessages(m=>m.map((v,i)=>i===m.length-1?{...v,tools:(v.tools??[]).map(tool=>tool.toolCallId===ev.toolCallId?{...tool,result:ev.result??'',isError:ev.isError}:tool)}:v));
        if(ev.type==='tool_start')setStatus(`${t.tool}: ${ev.toolName.replace('student_','').replaceAll('_',' ')}`);
        if(ev.type==='tool_end'){setStatus(ev.isError?t.error:t.thinking);void changed();}
        if(ev.type==='done')setMessages(m=>m.map((v,i)=>i===m.length-1?{...v,content:ev.fullText}:v));
        if(ev.type==='error')throw new Error(ev.message);
        if(ev.type==='permission_request'){await submitChatPermission(id,envelope.turnId,ev.requestId,'deny','Use Scoreler study tools; unrestricted operations are disabled.');}
        if(ev.type==='question'){await abortChat(id,envelope.turnId);throw new Error(locale==='zh-CN'?'请在对话中直接回答，交互问卷暂未支持。':'Please answer in chat; interactive questionnaires are not supported yet.');}
      }
      void refreshHistory();await changed();
    }catch(e){if(!controller.signal.aborted){setPrompt(plainPrompt);setImages(sentImages);setDocuments(sentDocuments);notice(e instanceof Error?e.message:String(e));}}
    finally{setBusy(false);setThinking(false);setStatus('');turnRef.current='';}
  };
  const handledAutoSend=useRef('');
  useEffect(()=>{if(!autoSend)return;const timer=setTimeout(()=>{if(handledAutoSend.current===autoSend.id)return;handledAutoSend.current=autoSend.id;consumeAutoSend();void sendMessage(autoSend.text,true,autoSend.id,autoSend.images);},0);return()=>clearTimeout(timer);},[autoSend?.id]);
  const videoGroups=videosByMessage(messages,videos.filter(v=>v.sessionId===sessionId));
  return <div className="assistant-layout"><section className="chat">{openNote&&<DrawingEditor folderId={openNote.folderId} path={openNote.path} directory={openNote.path.split('/').slice(0,-1).join('/')} en={locale==='en'} close={()=>setOpenNote(null)} notice={notice} saved={changed}/>}<div className="chat-top"><span>Scoreler</span><button disabled={busy} className="text-button" onClick={()=>{setSessionId(null);setMessages([]);setImages([]);setDocuments([]);localStorage.removeItem('scoreler.session');}}><Plus size={15}/>{t.newChat}</button></div><div className="chat-scroll">{messages.length||videos.some(v=>v.sessionId===sessionId)?<div className="messages">{messages.map((m,i)=><Fragment key={`${i}-${m.timestamp}`}><article className={`message ${m.role}`}><span className="message-avatar">{m.role==='assistant'?<Mascot className="assistant-pet-icon"/>:<GraduationCap size={18}/>}</span><div><span className="message-author">{m.role==='assistant'?'Scoreler':locale==='en'?'You':'我'}</span>{m.images?.length?<div className="message-images">{m.images.map((image,index)=><a href={image.previewUrl} target="_blank" rel="noreferrer" key={index}><img src={image.previewUrl} alt={locale==='en'?'Attached screenshot':'附加的截图'}/></a>)}</div>:null}{m.role==='assistant'&&<ChatActivity message={m} active={busy&&i===messages.length-1} thinking={thinking&&i===messages.length-1} en={locale==='en'}/>}<Markdown>{(m.role==='user'?m.content.split('[Student response language preference:')[0].trim().replace(/\[([^\]]+)\]\(scoreler-document:[a-f0-9-]+\)/g,'📎 $1'):m.content)||'…'}</Markdown>{m.role==='assistant'&&<><ChatNoteLinks tools={m.tools} en={locale==='en'} open={setOpenNote}/><ChatDictationLinks tools={m.tools} en={locale==='en'} open={openDictation}/></>}</div></article>{videoGroups.has(i)&&<TeachingVideos videos={videoGroups.get(i)!} locale={locale} notice={notice}/>}</Fragment>)}{!messages.length&&<TeachingVideos videos={videoGroups.get(0)??[]} locale={locale} notice={notice}/>}<div ref={bottom}/></div>:<div className="chat-welcome"><h1>{t.assistantTitle}</h1><p>{t.assistantDescription}</p><div className="suggestions"><button onClick={()=>setPrompt(locale==='en'?'Create a short teaching video using my study files. Ask which topic if needed.':'请参考我的学习资料生成一个简短教学视频；如果主题不明确，请先问我。')}><Sparkles size={19}/>{locale==='en'?'Make a teaching video':'生成教学视频'}<ArrowUpRight size={15}/></button><button onClick={()=>setPrompt(t.hintPrompt)}><CircleHelp size={19}/>{t.hint}<ArrowUpRight size={15}/></button><button onClick={()=>setPrompt(t.planPrompt)}><CalendarDays size={19}/>{t.planWeek}<ArrowUpRight size={15}/></button><button onClick={()=>setPrompt(t.practicePrompt)}><ClipboardList size={19}/>{t.practice}<ArrowUpRight size={15}/></button></div></div>}</div><div className="composer-area">{status&&<div className="tool-status" role="status"><span className="pulse-dot"/>{status}</div>}<form className="composer" onPaste={e=>{const files=Array.from(e.clipboardData.items).filter(item=>item.kind==='file'&&item.type.startsWith('image/')).map(item=>item.getAsFile()).filter((file):file is File=>!!file);if(files.length){e.preventDefault();void addImages(files);}}} onSubmit={e=>{e.preventDefault();void sendMessage();}}><input ref={imageInput} className="visually-hidden" type="file" accept="image/png,image/jpeg,image/webp,image/gif,.pdf,.docx,.xlsx,.pptx,.md,.txt,.csv,.json" multiple onChange={e=>void addAttachments(Array.from(e.target.files??[]))}/>{images.length>0&&<div className="image-attachments">{images.map(image=><div key={image.id}><img src={`data:${image.mimeType};base64,${image.data}`} alt={image.name}/><button type="button" disabled={busy} aria-label={`${locale==='en'?'Remove image':'移除图片'}: ${image.name}`} onClick={()=>setImages(current=>current.filter(item=>item.id!==image.id))}><X size={13}/></button></div>)}</div>}{documents.length>0&&<div className="document-attachments">{documents.map(doc=><span key={doc.id}>📎 {doc.name}<button type="button" disabled={busy} aria-label={(locale==='en'?'Remove file: ':'移除文件：')+doc.name} onClick={()=>setDocuments(old=>old.filter(item=>item.id!==doc.id))}><X size={13}/></button></span>)}</div>}<ResizableChatInput locale={locale} aria-label={t.promptPlaceholder} placeholder={t.promptPlaceholder} rows={3} value={prompt} onChange={e=>setPrompt(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.nativeEvent.isComposing){e.preventDefault();e.currentTarget.form?.requestSubmit();}}}/><div><span><button className="icon-button" type="button" disabled={busy||readingImages} title={locale==='en'?'Attach pictures or study files':'添加图片或学习文件'} aria-label={locale==='en'?'Attach pictures or files':'添加图片或文件'} onClick={()=>imageInput.current?.click()}><Plus size={18}/></button><ModelPicker en={locale==='en'} disabled={busy} notice={notice}/>{readingImages?t.working:<><ShieldCheck size={13}/>{t.local}</>}</span>{busy?<button type="button" className="send" aria-label={t.stop} onClick={stop}><Square size={16}/></button>:<button type="submit" className="send" aria-label={t.send} disabled={(!prompt.trim()&&!images.length&&!documents.length)||readingImages}><Send size={17}/></button>}</div></form><p className="composer-note">{t.localDetail}</p></div></section><ChatHistory sessions={sessions} selected={sessionId} busy={busy} en={locale==='en'} notice={notice} open={id=>void open(id)} deleted={id=>{setSessions(old=>old.filter(s=>s.id!==id));if(sessionId===id){setSessionId(null);setMessages([]);setImages([]);setDocuments([]);localStorage.removeItem('scoreler.session');}}}/></div>;
}

function Exams({t,locale,exams,changed,ask,sendToAI,notice}:{t:Copy;locale:Locale;exams:PracticeTest[];changed:()=>Promise<void>;sendToAI:(s:string)=>void;ask:(s:string)=>void;notice:(s:string)=>void}) {
  const [selected,setSelected]=useState<PracticeTest|null>(null),[answers,setAnswers]=useState<string[]>([]),[review,setReview]=useState(false),[started,setStarted]=useState<number|null>(null),[tick,setTick]=useState(Date.now());
  useEffect(()=>{if(!started)return;const id=setInterval(()=>setTick(Date.now()),1000);return()=>clearInterval(id);},[started]);
  const open=async(exam:PracticeTest)=>{try{const attempt=await apiFetch<{answers:string[];submitted:boolean}|null>(`/api/student/attempts/${exam.id}`);setSelected(exam);setAnswers(attempt?.answers??exam.questions.map(()=>''));setReview(attempt?.submitted??false);setStarted(null);}catch(e){notice(String(e));}};
  const save=async(submitted=false)=>{if(!selected)return;try{await apiFetch(`/api/student/attempts/${selected.id}`,{method:'PUT',body:JSON.stringify({answers,submitted})});notice(t.answersSaved);if(submitted){setReview(true);setStarted(null);}}catch(e){notice(String(e));}};
  const remove=async(exam:PracticeTest)=>{if(!window.confirm(locale==='en'?`Delete “${exam.title}” and its saved answers?`:`删除“${exam.title}”及其已保存的作答？`))return;try{await apiFetch(`/api/student/exams/${encodeURIComponent(exam.id)}`,{method:'DELETE'});if(selected?.id===exam.id){setSelected(null);setStarted(null);}await changed();}catch(e){notice(String(e));}};
  const remaining=selected&&started?Math.max(0,selected.minutes*60-Math.floor((tick-started)/1000)):null;
  useEffect(()=>{if(remaining===0){setStarted(null);void save(true);}},[remaining]);
  return <><Heading title={t.examTitle} description={t.examDescription} action={<button className="primary" onClick={()=>ask(t.practicePrompt)}><Sparkles size={16}/>{t.generate}</button>}/>{<SubjectFolders items={exams} en={locale==='en'} kind="exams">{items=><div className="exam-grid">{items.map(exam=><section className="panel exam-card" key={exam.id}><span className="kind">{exam.subject}</span><h2>{exam.title}</h2><p>{exam.questions.length} · {exam.questions.reduce((n,q)=>n+q.marks,0)} {t.marks} · {exam.minutes} {t.minutes}</p><span className="practice-label">{t.generalPractice}</span><div className="button-row"><button className="text-button" onClick={()=>void open(exam)}>{t.takeTest}<ArrowRight size={15}/></button><ExportMenu en={locale==='en'} notice={notice} run={format=>downloadPracticePdf(exam,locale,format)}/><button className="text-button" onClick={()=>sendToAI(examPrompt(exam))}><MessageCircle size={15}/>{locale==='en'?'Send to AI':'发送给 AI'}</button><button className="text-button danger" onClick={()=>void remove(exam)}><Trash2 size={15}/>{t.delete}</button></div></section>)}</div>}</SubjectFolders>}
  {selected&&<Modal title={selected.title} close={()=>{void save(review);setSelected(null);setStarted(null);}}><div className="assessment"><div className="button-row"><ExportMenu en={locale==='en'} notice={notice} run={format=>downloadPracticePdf(selected,locale,format)}/><button className="text-button" onClick={()=>sendToAI(examPrompt(selected))}><MessageCircle size={15}/>{locale==='en'?'Send to AI':'发送给 AI'}</button></div><p className="practice-label">{t.generalPractice}</p><Markdown>{selected.instructions}</Markdown><div className="assessment-toolbar"><button className="text-button" onClick={()=>void downloadPracticePdf(selected,locale).catch(e=>notice(String(e)))}><Download size={15}/>PDF</button><span><Clock3 size={15}/> {remaining!==null?`${Math.floor(remaining/60)}:${String(remaining%60).padStart(2,'0')}`:`${selected.minutes} ${t.minutes}`}</span>{!review&&!started&&<button className="secondary" onClick={()=>{setStarted(Date.now());setTick(Date.now());}}>{locale==='en'?'Start timer':'开始计时'}</button>}<button className="secondary" onClick={()=>void save(false)}>{t.save}</button></div>{selected.questions.map((q,i)=><section className="assessment-question" key={i}><div className="section-heading"><h3>{i+1}. {q.topic}</h3><span>{q.marks} {t.marks}</span></div><Markdown>{q.prompt}</Markdown><label>{t.yourAnswer}<textarea rows={4} value={answers[i]??''} onChange={e=>setAnswers(a=>a.map((s,j)=>j===i?e.target.value:s))}/></label>{review&&<div className="correction"><h4>{t.scheme}</h4><ul>{q.markingPoints.map((p,j)=><li key={j}><Markdown>{p}</Markdown></li>)}</ul><button className="text-button" onClick={()=>ask(`Review my answer as assisted study feedback, not official grading. Explain awarded and missed marking points, quote evidence from my answer, and flag uncertainty.\nQuestion: ${q.prompt}\nMarks: ${q.marks}\nScheme: ${q.markingPoints.join('; ')}\nMy answer: ${answers[i]}`)}>{locale==='en'?'Discuss my answer with Scoreler':'请 Scoreler 分析作答'}<ArrowUpRight size={14}/></button></div>}</section>)}<button className="primary" onClick={()=>void save(true)}>{t.submit}<Check size={15}/></button>{selected.sources.length>0&&<><h3>{t.testSources}</h3>{selected.sources.map((s,i)=><p key={i}><a href={s.url} target="_blank" rel="noreferrer">{s.title}</a> · {s.checkedAt?new Date(s.checkedAt).toLocaleDateString(locale):t.sourceUnverified}</p>)}</>}<p className="quiet-note">{t.researchNote}</p></div></Modal>}</>;
}

function SettingsPage({t,locale,setLocale,dark,setDark,preferences,savePreferences,notice}:{t:Copy;locale:Locale;setLocale:(l:Locale)=>void;dark:boolean;setDark:(d:boolean)=>void;preferences:StudentPreferences;savePreferences:(p:StudentPreferences)=>Promise<unknown>;notice:(s:string)=>void}) {
  const [searchKey,setSearchKey]=useState('');
  const exportData=async()=>{try{const data=await apiFetch('/api/student/export');const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`${t.exportName}-${dayKey(new Date())}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){notice(String(e));}};
  return <><Heading title={t.settingsTitle} description={t.settingsDescription}/><div className="settings-grid"><div><CompanionSettings en={locale==='en'} notice={notice}/><BrowserPreference en={locale==='en'} notice={notice}/><MemoryPanel locale={locale} notice={notice}/><section className="panel settings-section"><h2><Globe2 size={18}/>{t.appearance}</h2><label>{t.uiLanguage}<select value={locale} onChange={e=>setLocale(e.target.value as Locale)}><option value="en">English</option><option value="zh-CN">简体中文</option></select></label><label>{locale==='en'?'Grade / curriculum':'年级 / 课程'}<select aria-label={locale==='en'?'Grade / curriculum':'年级 / 课程'} value={preferences.grade??''} onChange={e=>void savePreferences({...preferences,grade:e.target.value as StudentPreferences['grade']})}><option value="">{locale==='en'?'Select your grade':'请选择年级'}</option><option value="G10-PreIB">G10-PreIB</option><option value="G11-IBDP">G11-IBDP</option><option value="G12-IBDP">G12-IBDP</option></select></label><label>{t.responseLanguage}<select value={preferences.responseLanguage} onChange={e=>void savePreferences({...preferences,responseLanguage:e.target.value as StudentPreferences['responseLanguage']})}><option value="auto">{t.automatic}</option><option value="en">English</option><option value="zh-CN">简体中文</option></select></label><ThemePalette en={locale==='en'}/><CustomThemes en={locale==='en'} notice={notice}/><label>{t.theme}<div className="segmented"><button className={!dark?'selected':''} onClick={()=>setDark(false)}><Sun size={15}/>{t.light}</button><button className={dark?'selected':''} onClick={()=>setDark(true)}><Moon size={15}/>{t.dark}</button></div></label></section><section className="panel settings-section"><h2><Clock3 size={18}/>{t.reminders}</h2><label className="checkbox-label"><input type="checkbox" checked={preferences.reminders} onChange={e=>void savePreferences({...preferences,reminders:e.target.checked})}/>{t.reminders}</label></section><section className="panel settings-section"><h2><ShieldCheck size={18}/>{t.privacy}</h2><p>{t.privacyNote}</p><button className="secondary" onClick={()=>void exportData()}><Download size={15}/>{t.export}</button></section></div><div><SourceUpdates en={locale==='en'} notice={notice}/><ProviderSettings en={locale==='en'} notice={notice}/><section id="setup-web-search" className="panel settings-section"><h2><Search size={18}/>{t.searchKey}</h2><form onSubmit={e=>{e.preventDefault();void saveTavilySettings(searchKey).then(()=>{setSearchKey('');notice(t.saved);}).catch(e=>notice(String(e)));}}><label>{t.apiKey}<input required type="password" autoComplete="off" value={searchKey} onChange={e=>setSearchKey(e.target.value)}/></label><p className="quiet-note">{t.searchNote}</p><button className="secondary" type="submit">{t.saveSearch}</button></form></section></div></div></>;
}




